const repo=fileURLToPath(new URL('../',import.meta.url));
const readPinned=pin=>{const bytes=execFileSync('git',['show',pin.revision+':'+pin.file],{cwd:repo,maxBuffer:8*1024*1024});assert.equal(hash(bytes),pin.sha256);assert.equal(bytes.length,pin.bytes);assert.equal(crypto.createHash('sha1').update('blob '+bytes.length+'\0').update(bytes).digest('hex'),pin.blob);return bytes.toString('utf8');};
const uniform=input=>{const normal=input.replaceAll('\r\n','\n');return !normal.includes('\r')&&(input===normal||input===normal.replaceAll('\n','\r\n'));};
export function commerceMigrationPredecessor(input){assert.equal(typeof input,'string');assert(uniform(input),'Only whole LF or uniform CRLF');const current=readPinned(COMMERCE_RELEASE_PHASE2_SOURCE),text=input.replaceAll('\r\n','\n');assert.equal(text,current,'Only complete genuine current568 source');let prior=text;for(const h of ORIGINAL_INVERSES){assert.equal(prior.split(h.current).length-1,1);prior=prior.replace(h.current,()=>h.baseline);}assert.equal(hash(prior),COMMERCE_RELEASE_PHASE2_PREDECESSOR.sha256);assert.equal(Buffer.byteLength(prior),COMMERCE_RELEASE_PHASE2_PREDECESSOR.bytes);assert.equal((prior.match(/^CREATE TABLE IF NOT EXISTS \w+/gm)||[]).length,561);const historical=readPinned(HISTORICAL551);assert(current.startsWith(historical));const append=current.slice(historical.length);assert.equal(hash(append),COMMERCE_RELEASE_PHASE2_PREDECESSOR.appendSha256);assert.equal(Buffer.byteLength(append),COMMERCE_RELEASE_PHASE2_PREDECESSOR.appendBytes);assert(prior.endsWith(append),'All17 new tables remain in the whole derived561 variant');return prior;}
